schemas.schema-01-systematic.prisma:
/// System-wide configuration records expressed as scoped key-value pairs
/// with effective time windows. Other services read these to drive behavior
/// (e.g., rate limits, guardrails) without code changes. Records are
/// authored by administrators; historical states are retained via soft
/// delete and effective windows. References authoring users via {@link
/// civicdebateboard_users}.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_configurations {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Authoring user's {@link civicdebateboard_users.id}.
  created_by_user_id String? @db.Uuid

  /// Last updating user's {@link civicdebateboard_users.id}.
  updated_by_user_id String? @db.Uuid

  /// Business configuration key identifier within a scope. Examples:
  /// "rate_limits.post.create", "safety.moderation.enabled".
  key String

  /// Configuration value stored as string. Application interprets typed
  /// semantics (e.g., JSON, number, boolean) externally.
  value String

  /// Logical scope of the configuration (e.g., "global", "env:prod",
  /// "region:KR"). Enables parallel keys per scope.
  scope String

  /// Human-readable explanation of the configuration and its intended effect.
  description String?

  /// When this configuration becomes effective. Used for rollout scheduling
  /// and audit context.
  effective_from DateTime @db.Timestamptz

  /// Optional end time after which the configuration is no longer effective.
  effective_to DateTime? @db.Timestamptz

  /// Whether this configuration is considered active by control planes. Allows
  /// pre-seeding or retiring values.
  active Boolean

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp if the record is logically removed.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  createdByUser civicdebateboard_users? @relation("civicdebateboard_configurations_of_created_by_user_id", fields: [created_by_user_id], references: [id], onDelete: Cascade)
  updatedByUser civicdebateboard_users? @relation("civicdebateboard_configurations_of_updated_by_user_id", fields: [updated_by_user_id], references: [id], onDelete: Cascade)

  @@index([updated_by_user_id])

  @@unique([key, scope, effective_from])
  @@index([scope, key, created_at])
  @@index([active, scope, effective_from])
  @@index([created_by_user_id, created_at], map: "civicdebateboard_configurations_created_by_user_id_cre_9109f241")
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([value(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Feature flag definitions controlling progressive delivery and conditional
/// behavior across the platform. Supports scoped flags, partial rollouts,
/// and segmentation. Consumed by application services at read-time; authored
/// by administrators. References {@link civicdebateboard_users} for
/// authorship. rollout_percentage is validated by application/business logic
/// to be within [0, 100].
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_feature_toggles {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Authoring user's {@link civicdebateboard_users.id}.
  created_by_user_id String? @db.Uuid

  /// Last updating user's {@link civicdebateboard_users.id}.
  updated_by_user_id String? @db.Uuid

  /// Stable machine-readable flag code. Example: "posts.pre_moderation".
  code String

  /// Human-friendly name of the feature toggle.
  name String

  /// Detailed description explaining the flag purpose and safety
  /// considerations.
  description String?

  /// Primary on/off switch for the feature under the given scope.
  enabled Boolean

  /// Percentage-based rollout for gradual exposure (0–100).
  /// Application/business logic enforces bounds.
  rollout_percentage Int @db.Integer

  /// Optional audience or rule expression used to segment exposure (e.g.,
  /// role, region).
  target_segment String?

  /// Logical scope of the flag (e.g., "global", "env:staging", "region:KR").
  scope String

  /// Optional scheduled start for automatic enablement.
  start_at DateTime? @db.Timestamptz

  /// Optional scheduled end for automatic disablement.
  end_at DateTime? @db.Timestamptz

  /// Emergency kill switch default for safe rollback post-incident.
  kill_switch Boolean

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp if the toggle is retired.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  createdByUser civicdebateboard_users? @relation("civicdebateboard_feature_toggles_of_created_by_user_id", fields: [created_by_user_id], references: [id], onDelete: Cascade)
  updatedByUser civicdebateboard_users? @relation("civicdebateboard_feature_toggles_of_updated_by_user_id", fields: [updated_by_user_id], references: [id], onDelete: Cascade)

  civicdebateboard_experiments civicdebateboard_experiments[]

  @@index([updated_by_user_id])

  @@unique([code, scope])
  @@index([enabled, scope, rollout_percentage], map: "civicdebateboard_feature_toggles_enabled_scope_rollout_81243490")
  @@index([scope, start_at, end_at])
  @@index([created_by_user_id, created_at], map: "civicdebateboard_feature_toggles_created_by_user_id_cr_e1fd8529")
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([target_segment(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Versioned policy documents (e.g., moderation, privacy, safety) with
/// explicit lifecycle states and effective windows. Each row represents an
/// immutable version for a specific policy_code. Approval references the
/// responsible user in {@link civicdebateboard_users}.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_policy_versions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Approver user's {@link civicdebateboard_users.id}. Optional for
  /// drafts/unapproved versions.
  approved_by_user_id String? @db.Uuid

  /// Authoring user's {@link civicdebateboard_users.id}.
  created_by_user_id String? @db.Uuid

  /// Last updating user's {@link civicdebateboard_users.id}.
  updated_by_user_id String? @db.Uuid

  /// Stable identifier of the policy domain (e.g., "moderation", "privacy").
  policy_code String

  /// Monotonic version number for the given policy_code. Combined with
  /// policy_code to form a unique version.
  version Int @db.Integer

  /// Lifecycle status string (e.g., "draft", "active", "deprecated").
  status String

  /// Human-readable title of the policy version.
  title String

  /// URI pointing to the canonical policy body content (e.g., HTML/Markdown).
  body_uri String? @db.VarChar(80000)

  /// Start of the time window when this version is effective.
  effective_from DateTime @db.Timestamptz

  /// Optional end of the effective time window.
  effective_to DateTime? @db.Timestamptz

  /// Author or reviewer notes regarding changes or rationale.
  notes String?

  /// Approver notes or conditions attached during approval.
  approval_notes String?

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp for retired records.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  approvedByUser civicdebateboard_users? @relation("civicdebateboard_policy_versions_of_approved_by_user_id", fields: [approved_by_user_id], references: [id], onDelete: Cascade)
  createdByUser civicdebateboard_users? @relation("civicdebateboard_policy_versions_of_created_by_user_id", fields: [created_by_user_id], references: [id], onDelete: Cascade)
  updatedByUser civicdebateboard_users? @relation("civicdebateboard_policy_versions_of_updated_by_user_id", fields: [updated_by_user_id], references: [id], onDelete: Cascade)

  civicdebateboard_annotation_reviews civicdebateboard_annotation_reviews[]
  civicdebateboard_moderation_actions civicdebateboard_moderation_actions[]
  civicdebateboard_sanctions civicdebateboard_sanctions[]
  civicdebateboard_content_labels civicdebateboard_content_labels[]
  civicdebateboard_policy_acknowledgments civicdebateboard_policy_acknowledgments[]
  civicdebateboard_ad_campaigns civicdebateboard_ad_campaigns[]
  civicdebateboard_sponsorships civicdebateboard_sponsorships[]
  civicdebateboard_metric_registry_entries civicdebateboard_metric_registry_entries[]
  civicdebateboard_business_review_logs civicdebateboard_business_review_logs[]

  @@index([approved_by_user_id])
  @@index([updated_by_user_id])

  @@unique([policy_code, version])
  @@index([policy_code, effective_from])
  @@index([status, effective_from])
  @@index([effective_from, effective_to], map: "civicdebateboard_policy_versions_effective_from_effect_f6fdde03")
  @@index([created_by_user_id, created_at], map: "civicdebateboard_policy_versions_created_by_user_id_cr_dc0cb2a4")
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Catalog of sanction types available to moderation workflows, including
/// default durations and severity calibration. Used to ensure consistent
/// enforcement decisions across cases. Authored by admins; referenced across
/// {@link civicdebateboard_moderation_actions} and related entities
/// conceptually (foreign keys not required here).
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_sanction_catalogs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Authoring user's {@link civicdebateboard_users.id}.
  created_by_user_id String? @db.Uuid

  /// Last updating user's {@link civicdebateboard_users.id}.
  updated_by_user_id String? @db.Uuid

  /// Stable sanction code (e.g., "warning", "mute_24h", "suspension_7d").
  code String

  /// Human-friendly label for the sanction type.
  name String

  /// Explanation of when and how this sanction should be used, per policy.
  description String?

  /// Default duration in hours to apply when not overridden by case context.
  default_duration_hours Int? @db.Integer

  /// Maximum permissible duration in hours for this sanction type.
  max_duration_hours Int? @db.Integer

  /// Normalized severity level for calibration and escalation (e.g., 0–3).
  severity_level Int @db.Integer

  /// Comma-separated role names indicating applicability (e.g.,
  /// "member,verifiedMember"). Purely informational.
  applies_to_roles String?

  /// Optional linking text to the policy category this sanction addresses
  /// (business label, not FK).
  policy_category String?

  /// Whether this catalog entry is active and available for selection.
  active Boolean

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp for deprecation without loss of history.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  createdByUser civicdebateboard_users? @relation("civicdebateboard_sanction_catalogs_of_created_by_user_id", fields: [created_by_user_id], references: [id], onDelete: Cascade)
  updatedByUser civicdebateboard_users? @relation("civicdebateboard_sanction_catalogs_of_updated_by_user_id", fields: [updated_by_user_id], references: [id], onDelete: Cascade)

  civicdebateboard_sanctions civicdebateboard_sanctions[]

  @@index([updated_by_user_id])

  @@unique([code])
  @@index([severity_level, active])
  @@index([active, created_at])
  @@index([created_by_user_id, created_at], map: "civicdebateboard_sanction_catalogs_created_by_user_id__45f8ab4a")
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Time-bounded elevated-protection windows for civic events (e.g.,
/// elections) by region. Used to prioritize moderation SLAs and apply
/// special safeguards. The active field is not a computed value; it is an
/// operator-controlled state (or maintained by a scheduler) persisted for
/// operational control, not a derived/calculated column. Configured by
/// admins and referenced by moderation and notification systems.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_election_windows {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Authoring user's {@link civicdebateboard_users.id}.
  created_by_user_id String? @db.Uuid

  /// Last updating user's {@link civicdebateboard_users.id}.
  updated_by_user_id String? @db.Uuid

  /// Region or jurisdiction code (e.g., ISO 3166-2 or service-defined region
  /// identifier).
  region_code String

  /// Human-friendly name of the election window or civic event.
  name String

  /// Detailed context of the event and applicable safeguards.
  description String?

  /// Start datetime of the elevated-protection period.
  starts_at DateTime @db.Timestamptz

  /// End datetime of the elevated-protection period.
  ends_at DateTime @db.Timestamptz

  /// Operator-controlled flag indicating whether this window is currently
  /// active. Not a derived/calculated field.
  active Boolean

  /// Optional priority tier for routing (lower number indicates higher
  /// priority).
  priority_tier Int? @db.Integer

  /// Optional reference URL with authoritative information about the event.
  reference_uri String? @db.VarChar(80000)

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp if this window is withdrawn.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  createdByUser civicdebateboard_users? @relation("civicdebateboard_election_windows_of_created_by_user_id", fields: [created_by_user_id], references: [id], onDelete: Cascade)
  updatedByUser civicdebateboard_users? @relation("civicdebateboard_election_windows_of_updated_by_user_id", fields: [updated_by_user_id], references: [id], onDelete: Cascade)

  civicdebateboard_ad_campaigns civicdebateboard_ad_campaigns[]

  @@index([updated_by_user_id])

  @@unique([region_code, name, starts_at], map: "civicdebateboard_election_windows_region_code_name_sta_95b4674f")
  @@index([region_code, starts_at, ends_at], map: "civicdebateboard_election_windows_region_code_starts_a_75bc9e47")
  @@index([active, starts_at])
  @@index([created_by_user_id, created_at], map: "civicdebateboard_election_windows_created_by_user_id_c_91b9f522")
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

