/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_users {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// User's unique email address used for account communications and
  /// credential login.
  email String

