schemas.schema-04-discussions.prisma:
/// Discussion thread container. Each thread groups one root post and all
/// descendant comments. Maintains locking state and ownership metadata. The
/// root post is uniquely referenced via {@link civicdebateboard_posts.id}
/// when set. Posts reference this model via {@link
/// civicdebateboard_posts.thread_id}.
///
/// @namespace Discussions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_threads {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Creator's {@link civicdebateboard_users.id}.
  created_by_user_id String @db.Uuid

  /// Whether the thread is locked for new comments and edits by non-staff.
  locked Boolean

  /// Creation timestamp of the thread.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp of the thread record.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp. Null when active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  createdBy civicdebateboard_users @relation(fields: [created_by_user_id], references: [id], onDelete: Cascade)

  civicdebateboard_posts civicdebateboard_posts[]
  civicdebateboard_notifications civicdebateboard_notifications[]
  civicdebateboard_subscription_targets civicdebateboard_subscription_targets[]

  @@index([created_by_user_id, created_at])
  @@index([locked, created_at])
}

/// Root discussion items authored by users. Belong to a {@link
/// civicdebateboard_threads} and exactly one taxonomy category (FK to {@link
/// civicdebateboard_categories}). Supports expert tagging for verified
/// members. Edit history captured in {@link civicdebateboard_post_edits}.
/// State transitions logged in {@link civicdebateboard_content_states}.
/// Added an index on (expert_tagged, created_at) to support expert-content
/// discovery and listings.
///
/// @namespace Discussions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_posts {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged thread's {@link civicdebateboard_threads.id}
  thread_id String @db.Uuid

  /// Author user's {@link civicdebateboard_users.id}
  author_user_id String @db.Uuid

  /// Chosen category's {@link civicdebateboard_categories.id}
  category_id String @db.Uuid

  /// Post title (business validation 10–150 chars enforced in application).
  title String

  /// Main content body (business validation 20–50,000 chars enforced in
  /// application).
  body String

  /// Whether the post is marked as expert content by a verified member or
  /// admin.
  expert_tagged Boolean

  /// Short expertise context note provided when expert_tagged is true
  /// (policy-defined length).
  expertise_note String?

  /// Creation timestamp of the post.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp of the post record.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp. Null when active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  thread civicdebateboard_threads @relation(fields: [thread_id], references: [id], onDelete: Cascade)
  author civicdebateboard_users @relation(fields: [author_user_id], references: [id], onDelete: Cascade)
  category civicdebateboard_categories @relation(fields: [category_id], references: [id], onDelete: Cascade)

  civicdebateboard_post_topics civicdebateboard_post_topics[]
  civicdebateboard_post_tags civicdebateboard_post_tags[]
  civicdebateboard_category_changes civicdebateboard_category_changes[]
  civicdebateboard_post_content_warnings civicdebateboard_post_content_warnings[]
  civicdebateboard_comments civicdebateboard_comments[]
  civicdebateboard_post_edits civicdebateboard_post_edits[]
  civicdebateboard_attachments civicdebateboard_attachments[]
  civicdebateboard_content_states civicdebateboard_content_states[]
  civicdebateboard_mentions civicdebateboard_mentions[]
  civicdebateboard_reactions civicdebateboard_reactions[]
  civicdebateboard_votes civicdebateboard_votes[]
  civicdebateboard_claim_excerpts civicdebateboard_claim_excerpts[]
  civicdebateboard_reports civicdebateboard_reports[]
  civicdebateboard_moderation_cases civicdebateboard_moderation_cases[]
  civicdebateboard_content_labels civicdebateboard_content_labels[]
  civicdebateboard_notifications civicdebateboard_notifications[]
  civicdebateboard_subscription_targets civicdebateboard_subscription_targets[]
  civicdebateboard_bookmarks civicdebateboard_bookmarks[]
  civicdebateboard_ad_placements civicdebateboard_ad_placements[]
  civicdebateboard_sponsored_surfaces civicdebateboard_sponsored_surfaces[]

  @@index([thread_id, created_at])
  @@index([author_user_id, created_at])
  @@index([category_id, created_at])
  @@index([expert_tagged, created_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Replies within a thread associated to a specific {@link
/// civicdebateboard_posts}. Supports hierarchical replies via optional
/// parent self-reference. Edit history captured in {@link
/// civicdebateboard_comment_edits}. State transitions logged in {@link
/// civicdebateboard_content_states}. Added an index on (parent_id,
/// created_at) to optimize reply pagination.
///
/// @namespace Discussions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_comments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent post's {@link civicdebateboard_posts.id}
  post_id String @db.Uuid

  /// Optional parent comment's {@link civicdebateboard_comments.id} for nested
  /// replies.
  parent_id String? @db.Uuid

  /// Author user's {@link civicdebateboard_users.id}
  author_user_id String @db.Uuid

  /// Comment content body (business validation 1–20,000 chars enforced in
  /// application).
  body String

  /// Creation timestamp of the comment.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp of the comment record.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp. Null when active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  post civicdebateboard_posts @relation(fields: [post_id], references: [id], onDelete: Cascade)
  parent civicdebateboard_comments? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)
  author civicdebateboard_users @relation(fields: [author_user_id], references: [id], onDelete: Cascade)

  recursive civicdebateboard_comments[] @relation("recursive")
  civicdebateboard_comment_edits civicdebateboard_comment_edits[]
  civicdebateboard_attachments civicdebateboard_attachments[]
  civicdebateboard_content_states civicdebateboard_content_states[]
  civicdebateboard_mentions civicdebateboard_mentions[]
  civicdebateboard_reactions civicdebateboard_reactions[]
  civicdebateboard_votes civicdebateboard_votes[]
  civicdebateboard_claim_excerpts civicdebateboard_claim_excerpts[]
  civicdebateboard_reports civicdebateboard_reports[]
  civicdebateboard_moderation_cases civicdebateboard_moderation_cases[]
  civicdebateboard_content_labels civicdebateboard_content_labels[]
  civicdebateboard_notifications civicdebateboard_notifications[]
  civicdebateboard_bookmarks civicdebateboard_bookmarks[]

  @@index([post_id, created_at])
  @@index([post_id, parent_id, created_at])
  @@index([author_user_id, created_at])
  @@index([parent_id, created_at])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Immutable snapshot of a post edit. Captures the edited content version,
/// optional category at edit time, who edited, and when. Enables audit
/// trails and restoration without denormalizing into the main entity.
/// Related post: {@link civicdebateboard_posts}.
///
/// @namespace Discussions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_post_edits {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Edited post's {@link civicdebateboard_posts.id}.
  post_id String @db.Uuid

  /// Editor actor's {@link civicdebateboard_users.id}.
  editor_user_id String @db.Uuid

  /// Category at the time of this edit. References {@link
  /// civicdebateboard_categories.id}. Optional because category changes may be
  /// tracked elsewhere.
  snapshot_category_id String? @db.Uuid

  /// Edited post title at this snapshot.
  title String

  /// Edited post body at this snapshot.
  body String

  /// Expert tag value at this snapshot.
  expert_tagged Boolean

  /// Expertise note value at this snapshot (if any).
  expertise_note String?

  /// Editor-provided reason for the edit, if supplied.
  reason String?

  /// Whether the edit is considered material/significant under policy (affects
  /// visibility/rereview).
  material Boolean

  /// Edit snapshot creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Technical update timestamp for the snapshot record.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp of the snapshot record, if ever retracted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  post civicdebateboard_posts @relation(fields: [post_id], references: [id], onDelete: Cascade)
  editor civicdebateboard_users @relation(fields: [editor_user_id], references: [id], onDelete: Cascade)
  snapshotCategory civicdebateboard_categories? @relation(fields: [snapshot_category_id], references: [id], onDelete: Cascade)

  @@index([snapshot_category_id])

  @@index([post_id, created_at])
  @@index([editor_user_id, created_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Immutable snapshot of a comment edit. Captures edited content, who
/// edited, and when for auditability. Related comment: {@link
/// civicdebateboard_comments}.
///
/// @namespace Discussions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_comment_edits {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Edited comment's {@link civicdebateboard_comments.id}.
  comment_id String @db.Uuid

  /// Editor actor's {@link civicdebateboard_users.id}.
  editor_user_id String @db.Uuid

  /// Edited comment body at this snapshot.
  body String

  /// Editor-provided reason for the edit, if supplied.
  reason String?

  /// Whether the edit is considered material/significant under policy (affects
  /// rereview).
  material Boolean

  /// Edit snapshot creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Technical update timestamp for the snapshot record.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp of the snapshot record, if applicable.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  comment civicdebateboard_comments @relation(fields: [comment_id], references: [id], onDelete: Cascade)
  editor civicdebateboard_users @relation(fields: [editor_user_id], references: [id], onDelete: Cascade)

  @@index([comment_id, created_at])
  @@index([editor_user_id, created_at])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// File attachments associated with either a {@link civicdebateboard_posts}
/// or a {@link civicdebateboard_comments}. Stores only raw metadata (URI,
/// mime type, size) and uploader identity. Accessibility alt_text is stored
/// and may be mandated by policy for images. No binary content is stored
/// here.
///
/// @namespace Discussions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_attachments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent post's {@link civicdebateboard_posts.id} when the attachment
  /// belongs to a post.
  post_id String? @db.Uuid

  /// Parent comment's {@link civicdebateboard_comments.id} when the attachment
  /// belongs to a comment.
  comment_id String? @db.Uuid

  /// Uploader user's {@link civicdebateboard_users.id}.
  uploader_user_id String @db.Uuid

  /// Canonical URI to the stored file (object storage, CDN, etc.).
  file_uri String @db.VarChar(80000)

  /// MIME type of the stored file.
  mime_type String

  /// Accessibility alt text (required by policy for images; optional for
  /// non-image files).
  alt_text String?

  /// File size in bytes for quota and validation purposes.
  size_bytes Int @db.Integer

  /// Attachment creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for the attachment record.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp. Null when active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  post civicdebateboard_posts? @relation(fields: [post_id], references: [id], onDelete: Cascade)
  comment civicdebateboard_comments? @relation(fields: [comment_id], references: [id], onDelete: Cascade)
  uploader civicdebateboard_users @relation(fields: [uploader_user_id], references: [id], onDelete: Cascade)

  @@unique([post_id, file_uri])
  @@unique([comment_id, file_uri])
  @@index([uploader_user_id, created_at])
  @@index([post_id, created_at])
  @@index([comment_id, created_at])
}

/// Temporal log of content visibility and enforcement states for posts and
/// comments. Records who applied the state, human-readable reason, and
/// visibility flags. Latest state is determined at query time or external
/// materialized views. Targets one of {@link civicdebateboard_posts} or
/// {@link civicdebateboard_comments}. Added composite indexes on (state,
/// created_at) and (visibility, created_at) for operational queries.
///
/// @namespace Discussions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_content_states {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Target post's {@link civicdebateboard_posts.id} when the state applies to
  /// a post.
  post_id String? @db.Uuid

  /// Target comment's {@link civicdebateboard_comments.id} when the state
  /// applies to a comment.
