/// Per-user notification preferences controlling delivery channels,
/// bundling, digest scheduling, and quiet hours. This is a 1:1 extension of
/// {@link civicdebateboard_users} and drives how notifications are sent or
/// suppressed. Used by notification pipelines to respect user
/// locale/timezone behavior and quiet hours.
///
/// @namespace Notifications
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_notification_preferences {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Owner user's {@link civicdebateboard_users.id}. Exactly one preferences
  /// row per user.
  civicdebateboard_user_id String @db.Uuid

  /// Default delivery mode for notifications: values like "instant" or
  /// "digest" chosen by the user.
  default_delivery_mode String

  /// Whether in-app notifications are enabled for the user.
  enable_in_app Boolean

  /// Whether email notifications are enabled for the user.
  enable_email Boolean

  /// Whether push notifications are enabled for the user.
  enable_push Boolean

  /// Window in minutes to bundle multiple notifications into a single group to
  /// reduce noise.
  bundle_window_minutes Int @db.Integer

  /// Whether a periodic digest is enabled for the user.
  digest_enabled Boolean

  /// Local-hour (0–23) at which the digest should be delivered for the user.
  /// Null when digest is disabled.
  digest_hour_local Int? @db.Integer

  /// Quiet hours start minute of day (0–1439) in the user’s locale. Null when
  /// not configured.
  quiet_hours_start_minute Int? @db.Integer

  /// Quiet hours end minute of day (0–1439) in the user’s locale. Null when
  /// not configured.
  quiet_hours_end_minute Int? @db.Integer

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp, if the record is logically removed.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user civicdebateboard_users @relation(fields: [civicdebateboard_user_id], references: [id], onDelete: Cascade, map: "civicdebateboard_notification_preferences_civicdebateb_9cc5868c")

  @@unique([civicdebateboard_user_id], map: "civicdebateboard_notification_preferences_civicdebateb_b05cd4da")
  @@index([digest_enabled, digest_hour_local], map: "civicdebateboard_notification_preferences_digest_enabl_d99529b0")
  @@index([bundle_window_minutes, enable_email, enable_push], map: "civicdebateboard_notification_preferences_bundle_windo_e16d3fb0")
}

/// User-facing notification records representing events like replies,
/// mentions, moderation decisions, appeals, annotations, or other system
/// updates. Each notification belongs to a recipient {@link
/// civicdebateboard_users} and may reference related domain objects for
/// context. Optionally linked to a {@link civicdebateboard_digests} when
/// delivered in a batch.
///
/// @namespace Notifications
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_notifications {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Recipient user's {@link civicdebateboard_users.id}.
  civicdebateboard_user_id String @db.Uuid

  /// Related post's {@link civicdebateboard_posts.id} when the notification
  /// concerns a post.
  civicdebateboard_post_id String? @db.Uuid

  /// Related comment's {@link civicdebateboard_comments.id} when the
  /// notification concerns a comment or reply.
  civicdebateboard_comment_id String? @db.Uuid

  /// Related thread's {@link civicdebateboard_threads.id} when the
  /// notification is thread-scoped.
  civicdebateboard_thread_id String? @db.Uuid

  /// Related moderation action's {@link
  /// civicdebateboard_moderation_actions.id} for enforcement outcomes.
  civicdebateboard_moderation_action_id String? @db.Uuid

  /// Related appeal decision's {@link civicdebateboard_appeal_decisions.id}
  /// when appeals resolve.
  civicdebateboard_appeal_decision_id String? @db.Uuid

  /// Related annotation's {@link civicdebateboard_annotations.id} for
  /// fact-check visibility or status changes.
  civicdebateboard_annotation_id String? @db.Uuid

  /// Related report's {@link civicdebateboard_reports.id} for report
  /// acknowledgements or outcomes.
  civicdebateboard_report_id String? @db.Uuid

  /// Linked digest's {@link civicdebateboard_digests.id} when the notification
  /// is delivered within a digest.
  civicdebateboard_digest_id String? @db.Uuid

  /// Business category for the notification (e.g., reply, mention,
  /// moderation_decision, appeal_result, annotation_published).
  category String

  /// Short subject or title shown to the user when applicable.
  title String?

  /// Human-readable body text for the notification when applicable.
  body String?

  /// Delivery mode used: "instant" or "digest" at the time of send.
  delivery_mode String

  /// Channel used to deliver the notification (e.g., in_app, email, push).
  channel String

  /// Time the notification was sent via its channel. Null for pending items.
  sent_at DateTime? @db.Timestamptz

  /// Time the notification was read by the recipient. Null if unread.
  read_at DateTime? @db.Timestamptz

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp, if the record is logically removed.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  recipient civicdebateboard_users @relation(fields: [civicdebateboard_user_id], references: [id], onDelete: Cascade)
  post civicdebateboard_posts? @relation(fields: [civicdebateboard_post_id], references: [id], onDelete: Cascade)
  comment civicdebateboard_comments? @relation(fields: [civicdebateboard_comment_id], references: [id], onDelete: Cascade)
  thread civicdebateboard_threads? @relation(fields: [civicdebateboard_thread_id], references: [id], onDelete: Cascade)
  moderationAction civicdebateboard_moderation_actions? @relation(fields: [civicdebateboard_moderation_action_id], references: [id], onDelete: Cascade, map: "civicdebateboard_notifications_civicdebateboard_modera_48fe08bc")
  appealDecision civicdebateboard_appeal_decisions? @relation(fields: [civicdebateboard_appeal_decision_id], references: [id], onDelete: Cascade, map: "civicdebateboard_notifications_civicdebateboard_appeal_be72efb4")
  annotation civicdebateboard_annotations? @relation(fields: [civicdebateboard_annotation_id], references: [id], onDelete: Cascade, map: "civicdebateboard_notifications_civicdebateboard_annota_e9acf8b0")
  report civicdebateboard_reports? @relation(fields: [civicdebateboard_report_id], references: [id], onDelete: Cascade)
  digest civicdebateboard_digests? @relation(fields: [civicdebateboard_digest_id], references: [id], onDelete: Cascade)

  civicdebateboard_notification_failures civicdebateboard_notification_failures[]

  @@index([civicdebateboard_post_id])
  @@index([civicdebateboard_comment_id])
  @@index([civicdebateboard_thread_id])
  @@index([civicdebateboard_moderation_action_id], map: "civicdebateboard_notifications_civicdebateboard_modera_ac63a2a8")
  @@index([civicdebateboard_appeal_decision_id], map: "civicdebateboard_notifications_civicdebateboard_appeal_774a35bd")
  @@index([civicdebateboard_annotation_id], map: "civicdebateboard_notifications_civicdebateboard_annota_109e03f3")
  @@index([civicdebateboard_report_id])
  @@index([civicdebateboard_digest_id])

  @@index([civicdebateboard_user_id, created_at], map: "civicdebateboard_notifications_civicdebateboard_user_i_2b90e32e")
  @@index([civicdebateboard_user_id, read_at], map: "civicdebateboard_notifications_civicdebateboard_user_i_bef33536")
  @@index([category, created_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Delivery failures and retry attempts for notifications across channels.
/// Provides evidence and diagnostics for support, and enables backoff
/// strategies. Each record links to a {@link civicdebateboard_notifications}
/// and may reference the user and device used.
///
/// @namespace Notifications
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_notification_failures {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Failed notification's {@link civicdebateboard_notifications.id}.
  civicdebateboard_notification_id String @db.Uuid

  /// Affected user's {@link civicdebateboard_users.id}. Optional because some
  /// failures are channel-only and can be inferred from the notification.
  civicdebateboard_user_id String? @db.Uuid

  /// Target device's {@link civicdebateboard_user_devices.id} for push or
  /// device-scoped failures.
  civicdebateboard_user_device_id String? @db.Uuid

  /// Delivery channel on which the failure occurred (in_app, email, push).
  channel String

  /// Machine-readable error code returned by downstream provider or system.
  error_code String

  /// Human-readable error details. May be truncated as appropriate.
  error_message String?

  /// Monotonic attempt number for this notification delivery.
  attempt Int @db.Integer

  /// Timestamp when the failure occurred.
  occurred_at DateTime @db.Timestamptz

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp, if the record is logically removed.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  notification civicdebateboard_notifications @relation(fields: [civicdebateboard_notification_id], references: [id], onDelete: Cascade, map: "civicdebateboard_notification_failures_civicdebateboar_1bc357de")
  user civicdebateboard_users? @relation(fields: [civicdebateboard_user_id], references: [id], onDelete: Cascade, map: "civicdebateboard_notification_failures_civicdebateboar_835532b9")
  userDevice civicdebateboard_user_devices? @relation(fields: [civicdebateboard_user_device_id], references: [id], onDelete: Cascade, map: "civicdebateboard_notification_failures_civicdebateboar_a43ebc77")

  @@index([civicdebateboard_user_device_id], map: "civicdebateboard_notification_failures_civicdebateboar_fa56f49a")

  @@index([civicdebateboard_notification_id, occurred_at], map: "civicdebateboard_notification_failures_civicdebateboar_e5a2f270")
  @@index([civicdebateboard_user_id, occurred_at], map: "civicdebateboard_notification_failures_civicdebateboar_f690c0c7")
  @@index([channel, occurred_at])
}

/// Scheduled and sent digest batches per user, defining the covered period
/// and delivery status. Notifications delivered via digest can link back
/// using {@link civicdebateboard_notifications.civicdebateboard_digest_id}.
///
/// @namespace Notifications
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_digests {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Recipient user's {@link civicdebateboard_users.id}.
  civicdebateboard_user_id String @db.Uuid

  /// Inclusive start of the digest period in canonical time.
  period_start_at DateTime @db.Timestamptz

  /// Exclusive end of the digest period in canonical time.
  period_end_at DateTime @db.Timestamptz

  /// When this digest is scheduled to be delivered relative to the user’s
  /// local preference.
  scheduled_for DateTime @db.Timestamptz

  /// When the digest was actually sent. Null if pending or failed before send.
  sent_at DateTime? @db.Timestamptz

  /// Status of the digest (e.g., scheduled, sent, failed, cancelled).
  status String

  /// Number of items included in the digest at the time of send.
  item_count Int @db.Integer

  /// Timezone identifier captured at scheduling time for audit and
  /// reconstruction (e.g., Asia/Seoul).
  timezone_at_scheduling String?

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp, if the record is logically removed.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user civicdebateboard_users @relation(fields: [civicdebateboard_user_id], references: [id], onDelete: Cascade)

  civicdebateboard_notifications civicdebateboard_notifications[]

  @@unique([civicdebateboard_user_id, period_start_at, period_end_at], map: "civicdebateboard_digests_civicdebateboard_user_id_peri_90f84c3c")
  @@index([civicdebateboard_user_id, scheduled_for], map: "civicdebateboard_digests_civicdebateboard_user_id_sche_80d7fdb1")
  @@index([status, scheduled_for])
}

/// Subscriber-level configuration for content updates independent of
/// specific targets. A subscription belongs to a {@link
/// civicdebateboard_users} account and defines preferences such as delivery
/// mode and whether it participates in digests. Specific targets (authors,
/// threads, posts, topics, categories) are attached via {@link
/// civicdebateboard_subscription_targets}. Enforces at most one subscription
/// per user per delivery mode to prevent duplication across targets.
///
/// @namespace Notifications
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_subscriptions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Subscriber user's {@link civicdebateboard_users.id}.
  civicdebateboard_user_id String @db.Uuid

  /// Preferred delivery mode for this subscription (e.g., instant or digest).
  delivery_mode String

  /// Whether notifications from targets under this subscription are muted.
  muted Boolean

  /// Whether this subscription contributes items to periodic digests.
  digest_enabled Boolean

  /// Whether the subscription is currently active.
  active Boolean

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp, if the record is logically removed.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  subscriber civicdebateboard_users @relation(fields: [civicdebateboard_user_id], references: [id], onDelete: Cascade)

  civicdebateboard_subscription_targets civicdebateboard_subscription_targets[]

  @@unique([civicdebateboard_user_id, delivery_mode], map: "civicdebateboard_subscriptions_civicdebateboard_user_i_a4fe388f")
  @@index([civicdebateboard_user_id, active, muted, digest_enabled], map: "civicdebateboard_subscriptions_civicdebateboard_user_i_153a2c13")
}

/// Junction table linking a {@link civicdebateboard_subscriptions} record to
/// one specific target entity. Supports multiple target kinds via nullable
/// foreign keys with strong referential integrity (author user, thread,
/// post, topic, category). The target_type classifier aids routing and
/// analytics while remaining non-authoritative compared to FKs.
///
/// @namespace Notifications
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_subscription_targets {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Owning subscription's {@link civicdebateboard_subscriptions.id}.
  civicdebateboard_subscription_id String @db.Uuid

  /// Target author user's {@link civicdebateboard_users.id} when following an
  /// author.
  civicdebateboard_user_id String? @db.Uuid

  /// Target thread's {@link civicdebateboard_threads.id} when following a
  /// thread.
  civicdebateboard_thread_id String? @db.Uuid

  /// Target post's {@link civicdebateboard_posts.id} when following a post.
  civicdebateboard_post_id String? @db.Uuid

  /// Target topic's {@link civicdebateboard_topics.id} when following a topic.
  civicdebateboard_topic_id String? @db.Uuid

  /// Target category's {@link civicdebateboard_categories.id} when following a
  /// category.
  civicdebateboard_category_id String? @db.Uuid

  /// Classifier for the target kind (author, thread, post, topic, category) to
  /// simplify routing and analytics.
  target_type String

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp, if the record is logically removed.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  subscription civicdebateboard_subscriptions @relation(fields: [civicdebateboard_subscription_id], references: [id], onDelete: Cascade, map: "civicdebateboard_subscription_targets_civicdebateboard_7c353dba")
  author civicdebateboard_users? @relation(fields: [civicdebateboard_user_id], references: [id], onDelete: Cascade, map: "civicdebateboard_subscription_targets_civicdebateboard_ae3b34fd")
  thread civicdebateboard_threads? @relation(fields: [civicdebateboard_thread_id], references: [id], onDelete: Cascade, map: "civicdebateboard_subscription_targets_civicdebateboard_887b7c3c")
  post civicdebateboard_posts? @relation(fields: [civicdebateboard_post_id], references: [id], onDelete: Cascade, map: "civicdebateboard_subscription_targets_civicdebateboard_e6fa0a52")
  topic civicdebateboard_topics? @relation(fields: [civicdebateboard_topic_id], references: [id], onDelete: Cascade, map: "civicdebateboard_subscription_targets_civicdebateboard_d4629fbd")
  category civicdebateboard_categories? @relation(fields: [civicdebateboard_category_id], references: [id], onDelete: Cascade, map: "civicdebateboard_subscription_targets_civicdebateboard_99eaa449")

  @@index([civicdebateboard_user_id], map: "civicdebateboard_subscription_targets_civicdebateboard_5acdd6a7")
  @@index([civicdebateboard_thread_id], map: "civicdebateboard_subscription_targets_civicdebateboard_a714820e")
  @@index([civicdebateboard_post_id], map: "civicdebateboard_subscription_targets_civicdebateboard_19dded12")
  @@index([civicdebateboard_topic_id], map: "civicdebateboard_subscription_targets_civicdebateboard_e81e23a6")
  @@index([civicdebateboard_category_id], map: "civicdebateboard_subscription_targets_civicdebateboard_d900383c")

  @@unique([civicdebateboard_subscription_id, civicdebateboard_user_id], map: "civicdebateboard_subscription_targets_civicdebateboard_f07a7d89")
  @@unique([civicdebateboard_subscription_id, civicdebateboard_thread_id], map: "civicdebateboard_subscription_targets_civicdebateboard_4a70c772")
  @@unique([civicdebateboard_subscription_id, civicdebateboard_post_id], map: "civicdebateboard_subscription_targets_civicdebateboard_cde11809")
  @@unique([civicdebateboard_subscription_id, civicdebateboard_topic_id], map: "civicdebateboard_subscription_targets_civicdebateboard_423d3776")
  @@unique([civicdebateboard_subscription_id, civicdebateboard_category_id], map: "civicdebateboard_subscription_targets_civicdebateboard_7a5cb379")
  @@index([civicdebateboard_subscription_id, created_at], map: "civicdebateboard_subscription_targets_civicdebateboard_e2bf0d4c")
  @@index([civicdebateboard_subscription_id, target_type], map: "civicdebateboard_subscription_targets_civicdebateboard_af0c3e76")
