schemas.schema-09-favorites.prisma:
/// Bookmarks created by a user to quickly return to important civic content.
/// A bookmark targets either a {@link civicdebateboard_posts} record or a
/// {@link civicdebateboard_comments} record (exactly one must be set at
/// application level). Prevents duplicates per user and target via composite
/// unique constraints. No denormalized content fields are stored; discovery
/// uses joins. Supports audit via temporal fields.
///
/// @namespace Favorites
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_bookmarks {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Owner user's {@link civicdebateboard_users.id}.
  civicdebateboard_user_id String @db.Uuid

  /// Bookmarked post's {@link civicdebateboard_posts.id}. Nullable when the
  /// bookmark targets a comment.
  civicdebateboard_post_id String? @db.Uuid

  /// Bookmarked comment's {@link civicdebateboard_comments.id}. Nullable when
  /// the bookmark targets a post.
  civicdebateboard_comment_id String? @db.Uuid

  /// Timestamp when the bookmark was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the bookmark was last updated.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp when the bookmark was removed by the user or
  /// system. Null when active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user civicdebateboard_users @relation(fields: [civicdebateboard_user_id], references: [id], onDelete: Cascade)
  post civicdebateboard_posts? @relation(fields: [civicdebateboard_post_id], references: [id], onDelete: Cascade)
  comment civicdebateboard_comments? @relation(fields: [civicdebateboard_comment_id], references: [id], onDelete: Cascade)

  @@unique([civicdebateboard_user_id, civicdebateboard_post_id], map: "civicdebateboard_bookmarks_civicdebateboard_user_id_ci_1efc1272")
  @@unique([civicdebateboard_user_id, civicdebateboard_comment_id], map: "civicdebateboard_bookmarks_civicdebateboard_user_id_ci_b3f3a543")
  @@index([civicdebateboard_user_id, created_at], map: "civicdebateboard_bookmarks_civicdebateboard_user_id_cr_1bf8292b")
  @@index([civicdebateboard_post_id, created_at], map: "civicdebateboard_bookmarks_civicdebateboard_post_id_cr_7f70d776")
  @@index([civicdebateboard_comment_id, created_at], map: "civicdebateboard_bookmarks_civicdebateboard_comment_id_9b26a9de")
}

/// Directed follow relationship where one user (follower) subscribes to
/// another user's public activity (followee). Both sides reference {@link
/// civicdebateboard_users}. Prevents duplicate follows via composite unique
/// constraint. Used to personalize feeds and notifications without
/// duplicating profile data.
///
/// @namespace Favorites
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_author_follows {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Follower user's {@link civicdebateboard_users.id}.
  follower_civicdebateboard_user_id String @db.Uuid

  /// Followed author's {@link civicdebateboard_users.id}.
  followee_civicdebateboard_user_id String @db.Uuid

  /// Timestamp when the follow was established.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the follow record was last updated.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp if the follow was unfollowed (null when active).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  follower civicdebateboard_users @relation("civicdebateboard_author_follows_of_follower_civicdebat_74acab5d", fields: [follower_civicdebateboard_user_id], references: [id], onDelete: Cascade, map: "civicdebateboard_author_follows_follower_civicdebatebo_97bc9ab8")
  followee civicdebateboard_users @relation("civicdebateboard_author_follows_of_followee_civicdebat_cc797e2f", fields: [followee_civicdebateboard_user_id], references: [id], onDelete: Cascade, map: "civicdebateboard_author_follows_followee_civicdebatebo_2990b41c")

  @@unique([follower_civicdebateboard_user_id, followee_civicdebateboard_user_id], map: "civicdebateboard_author_follows_follower_civicdebatebo_e8b31914")
  @@index([follower_civicdebateboard_user_id, created_at], map: "civicdebateboard_author_follows_follower_civicdebatebo_82167b39")
  @@index([followee_civicdebateboard_user_id, created_at], map: "civicdebateboard_author_follows_followee_civicdebatebo_d2361ad8")
}

/// Follow relationship where a user subscribes to updates from a specific
/// {@link civicdebateboard_topics} entity. Enables personalized feeds and
/// notifications for topic changes without denormalizing topic data.
///
/// @namespace Favorites
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_topic_follows {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Follower user's {@link civicdebateboard_users.id}.
  civicdebateboard_user_id String @db.Uuid

  /// Followed topic's {@link civicdebateboard_topics.id}.
  civicdebateboard_topic_id String @db.Uuid

  /// Timestamp when the topic follow was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the topic follow was last updated.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp when the topic follow was removed (null when
  /// active).
  deleted_at DateTime? @db.Timestamptz

