/// Time-bucketed KPI/metric observations tied to a registry entry. Stores
/// raw measured values per metric/period/segment to support analytics and
/// governance reporting. References {@link
/// civicdebateboard_metric_registry_entries}. Adds an index to accelerate
/// end-bounded window queries.
///
/// @namespace AnalyticsGovernance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_kpi_measurements {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Target registry metric's {@link
  /// civicdebateboard_metric_registry_entries.id}.
  metric_registry_entry_id String @db.Uuid

  /// Creator user's {@link civicdebateboard_users.id}.
  created_by_user_id String? @db.Uuid

  /// Start of the measurement period (inclusive).
  period_start DateTime @db.Timestamptz

  /// End of the measurement period (exclusive).
  period_end DateTime @db.Timestamptz

  /// Granularity of the period (e.g., daily, weekly, monthly).
  period_granularity String

  /// Measured numeric value for the KPI/metric in the specified period and
  /// segment.
  value Float @db.DoublePrecision

  /// Count of samples included in the measurement window.
  sample_size Int? @db.Integer

  /// Normalized key expressing the segment (e.g., role=member;region=kr).
  segment_key String?

  /// Human-readable description of the segment definition.
  segment_description String?

  /// Optional analyst or governance notes about this measurement.
  notes String?

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp if applicable.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  metric    civicdebateboard_metric_registry_entries @relation(fields: [metric_registry_entry_id], references: [id], onDelete: Cascade)
  createdBy civicdebateboard_users?                  @relation(fields: [created_by_user_id], references: [id], onDelete: Cascade)

  @@unique([metric_registry_entry_id, period_start, period_end, segment_key], map: "civicdebateboard_kpi_measurements_metric_registry_entr_c18eb067")
  @@index([created_by_user_id])
  @@index([metric_registry_entry_id, period_start], map: "civicdebateboard_kpi_measurements_metric_registry_entr_8a499577")
  @@index([period_granularity, period_start], map: "civicdebateboard_kpi_measurements_period_granularity_p_1207a77e")
  @@index([metric_registry_entry_id, period_end], map: "civicdebateboard_kpi_measurements_metric_registry_entr_4e996fad")
  @@index([segment_description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Experiment registry for A/B or multi-variant tests. Captures hypothesis,
/// governance status, schedule, and links to primary/secondary registry
/// metrics used for evaluation. Referenced by {@link
/// civicdebateboard_experiment_exposures} and {@link
/// civicdebateboard_experiment_results}.
///
/// @namespace AnalyticsGovernance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_experiments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Primary evaluation metric's {@link
  /// civicdebateboard_metric_registry_entries.id}.
  primary_metric_registry_entry_id String? @db.Uuid

  /// Secondary evaluation metric's {@link
  /// civicdebateboard_metric_registry_entries.id}.
  secondary_metric_registry_entry_id String? @db.Uuid

  /// Experiment creator user's {@link civicdebateboard_users.id}.
  created_by_user_id String? @db.Uuid

  /// Related feature toggle's {@link civicdebateboard_feature_toggles.id} if
  /// applicable.
  civicdebateboard_feature_toggle_id String? @db.Uuid

  /// Unique experiment code (e.g., exp_ama_badge_visibility).
  code String

  /// Human-readable experiment name.
  name String

  /// Business hypothesis being tested.
  hypothesis String?

  /// Lifecycle status (e.g., draft, running, paused, completed).
  status String

  /// Assignment unit (e.g., user, session).
  exposure_unit String

  /// Planned/actual start time.
  start_at DateTime? @db.Timestamptz

  /// Planned/actual end time.
  end_at DateTime? @db.Timestamptz

  /// Optional cap on concurrent exposures for safety/governance.
  max_concurrent_exposures Int? @db.Integer

  /// Operational or governance notes.
  notes String?

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp if applicable.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  primaryMetric   civicdebateboard_metric_registry_entries? @relation("civicdebateboard_experiments_of_primary_metric_registr_7ccfae54", fields: [primary_metric_registry_entry_id], references: [id], onDelete: Cascade, map: "civicdebateboard_experiments_primary_metric_registry_e_ed7e6086")
  secondaryMetric civicdebateboard_metric_registry_entries? @relation("civicdebateboard_experiments_of_secondary_metric_regis_5430c07b", fields: [secondary_metric_registry_entry_id], references: [id], onDelete: Cascade, map: "civicdebateboard_experiments_secondary_metric_registry_d5ac9f6f")
  createdBy       civicdebateboard_users?                   @relation(fields: [created_by_user_id], references: [id], onDelete: Cascade)
  featureToggle   civicdebateboard_feature_toggles?         @relation(fields: [civicdebateboard_feature_toggle_id], references: [id], onDelete: Cascade, map: "civicdebateboard_experiments_civicdebateboard_feature__8059c18d")

  civicdebateboard_experiment_exposures civicdebateboard_experiment_exposures[]
  civicdebateboard_experiment_results   civicdebateboard_experiment_results[]

  @@unique([code])
  @@index([secondary_metric_registry_entry_id], map: "civicdebateboard_experiments_secondary_metric_registry_a848a573")
  @@index([created_by_user_id])
  @@index([civicdebateboard_feature_toggle_id], map: "civicdebateboard_experiments_civicdebateboard_feature__e5055d60")
  @@index([status, start_at])
  @@index([primary_metric_registry_entry_id, status], map: "civicdebateboard_experiments_primary_metric_registry_e_d25765bb")
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([hypothesis(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Assignment records mapping experiment subjects to variants and cohorts.
/// Represents the M:N relation between {@link civicdebateboard_experiments}
/// and {@link civicdebateboard_users} with temporal context. Optionally
/// linked to {@link civicdebateboard_sessions} for device-level attribution.
/// Adds integrity guard for session-scoped experiments and an index to
/// accelerate variant tallies.
///
/// @namespace AnalyticsGovernance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_experiment_exposures {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Experiment's {@link civicdebateboard_experiments.id}.
  civicdebateboard_experiment_id String @db.Uuid

  /// Exposed user's {@link civicdebateboard_users.id}.
  civicdebateboard_user_id String @db.Uuid

  /// Optional session context's {@link civicdebateboard_sessions.id}.
  civicdebateboard_session_id String? @db.Uuid

  /// Assigned variant key (e.g., control, treatment_a).
  variant_key String

  /// Optional cohort key for segmentation (e.g., region=kr).
  cohort_key String?

  /// Timestamp when the exposure assignment occurred.
  assigned_at DateTime @db.Timestamptz

  /// Optional textual context for assignment (e.g., rule id, allocator).
  exposure_context String?

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp if applicable.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  experiment civicdebateboard_experiments @relation(fields: [civicdebateboard_experiment_id], references: [id], onDelete: Cascade, map: "civicdebateboard_experiment_exposures_civicdebateboard_729dd6e8")
  user       civicdebateboard_users       @relation(fields: [civicdebateboard_user_id], references: [id], onDelete: Cascade, map: "civicdebateboard_experiment_exposures_civicdebateboard_f4e80c05")
  session    civicdebateboard_sessions?   @relation(fields: [civicdebateboard_session_id], references: [id], onDelete: Cascade, map: "civicdebateboard_experiment_exposures_civicdebateboard_64468f56")

  @@unique([civicdebateboard_experiment_id, civicdebateboard_user_id], map: "civicdebateboard_experiment_exposures_civicdebateboard_7f59330f")
  @@unique([civicdebateboard_experiment_id, civicdebateboard_session_id], map: "civicdebateboard_experiment_exposures_civicdebateboard_22bb8822")
  @@index([civicdebateboard_session_id], map: "civicdebateboard_experiment_exposures_civicdebateboard_6715fe5d")
  @@index([civicdebateboard_experiment_id, assigned_at], map: "civicdebateboard_experiment_exposures_civicdebateboard_a51444a4")
  @@index([civicdebateboard_user_id, assigned_at], map: "civicdebateboard_experiment_exposures_civicdebateboard_e3df5677")
  @@index([civicdebateboard_experiment_id, variant_key], map: "civicdebateboard_experiment_exposures_civicdebateboard_173d0887")
}

/// Recorded analysis outcomes per experiment, metric, variant, and analysis
/// window. Provides auditable storage of statistical outputs without
/// denormalizing upstream data. References {@link
/// civicdebateboard_experiments} and {@link
/// civicdebateboard_metric_registry_entries}. Adds a composite index to
/// speed variant-sliced window retrieval.
///
/// @namespace AnalyticsGovernance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_experiment_results {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Experiment's {@link civicdebateboard_experiments.id}.
  civicdebateboard_experiment_id String @db.Uuid

  /// Evaluated metric's {@link civicdebateboard_metric_registry_entries.id}.
  metric_registry_entry_id String @db.Uuid

  /// Variant key for which the result applies (e.g., control, treatment_a).
  variant_key String

  /// Start of analysis window (inclusive).
  analysis_window_start DateTime @db.Timestamptz

  /// End of analysis window (exclusive).
  analysis_window_end DateTime @db.Timestamptz

  /// Measured effect or metric value computed for the window and variant.
  value Float @db.DoublePrecision

  /// Estimated standard error for the measurement.
  standard_error Float? @db.DoublePrecision

  /// P-value for hypothesis testing associated with the result.
  p_value Float? @db.DoublePrecision

  /// Whether the result meets pre-defined significance criteria.
  significant Boolean

  /// Analytical method identifier (e.g., t_test, CUPED).
  method String?

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp if applicable.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  experiment civicdebateboard_experiments             @relation(fields: [civicdebateboard_experiment_id], references: [id], onDelete: Cascade, map: "civicdebateboard_experiment_results_civicdebateboard_e_63b26cb3")
  metric     civicdebateboard_metric_registry_entries @relation(fields: [metric_registry_entry_id], references: [id], onDelete: Cascade, map: "civicdebateboard_experiment_results_metric_registry_en_1e446129")

  @@unique([civicdebateboard_experiment_id, metric_registry_entry_id, variant_key, analysis_window_start, analysis_window_end], map: "civicdebateboard_experiment_results_civicdebateboard_e_312f243f")
  @@index([civicdebateboard_experiment_id, created_at], map: "civicdebateboard_experiment_results_civicdebateboard_e_f2d8213f")
  @@index([metric_registry_entry_id, created_at], map: "civicdebateboard_experiment_results_metric_registry_en_41635e8f")
  @@index([civicdebateboard_experiment_id, variant_key, analysis_window_start], map: "civicdebateboard_experiment_results_civicdebateboard_e_820c6946")
}

/// Governance business review logs (weekly/monthly/quarterly). Records
/// period, status, summary, and accountable owners. Supports transparency
/// and audit for metrics reviews and decisions. References {@link
/// civicdebateboard_users} and {@link civicdebateboard_policy_versions}.
///
/// @namespace AnalyticsGovernance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model civicdebateboard_business_review_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Creator user's {@link civicdebateboard_users.id}.
  created_by_user_id String @db.Uuid

  /// Accountable owner's {@link civicdebateboard_users.id}.
  owner_user_id String @db.Uuid

  /// Referenced policy version's {@link civicdebateboard_policy_versions.id}
  /// for this review period.
  policy_version_id String? @db.Uuid

  /// Type of review (e.g., weekly_ops, monthly_business, quarterly_strategy).
  review_type String

  /// Start of the review period (inclusive).
  period_start DateTime @db.Timestamptz

  /// End of the review period (exclusive).
  period_end DateTime @db.Timestamptz

  /// Lifecycle status (e.g., drafted, published, amended).
  status String

  /// Human-readable summary of key outcomes and decisions.
  summary String

  /// Optional action items and owners recorded as plain text.
  action_items String?

  /// Optional URI to the detailed review document or dashboard.
  document_uri String? @db.VarChar(80000)

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp if applicable.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  createdBy     civicdebateboard_users            @relation("civicdebateboard_business_review_logs_of_created_by_user_id", fields: [created_by_user_id], references: [id], onDelete: Cascade)
  owner         civicdebateboard_users            @relation("civicdebateboard_business_review_logs_of_owner_user_id", fields: [owner_user_id], references: [id], onDelete: Cascade)
  policyVersion civicdebateboard_policy_versions? @relation(fields: [policy_version_id], references: [id], onDelete: Cascade)

  @@unique([review_type, period_start, period_end], map: "civicdebateboard_business_review_logs_review_type_peri_b9536cca")
  @@index([created_by_user_id])
  @@index([policy_version_id])
  @@index([status, period_start])
  @@index([owner_user_id, period_start], map: "civicdebateboard_business_review_logs_owner_user_id_pe_1ce21eba")
  @@index([summary(ops: raw("gin_trgm_ops"))], type: Gin)
}

